  const productionGaTrainingModuleIds = [
    'governance-basics',
    'approvals-authority',
    'evidence-audit-review',
    'github-lifecycle',
    'release-deploy-rollback',
    'secrets-handling',
    'runtime-external-agent-safety',
    'incident-disaster-recovery',
  ];
  const productionGaScenarios: readonly ProductionGaE2EScenario[] = [
    'all-pass',
    'patch-blocked',
    'verification-failed',
    'pr-blocked',
    'merge-blocked',
    'release-blocked',
    'deploy-blocked',
    'observe-blocked',
    'rollback-plan-missing',
    'rollback-failed',
    'child-hash-mismatch',
    'approval-blocked',
    'live-env-not-configured',
    'evidence-missing',
    'audit-gap',
  ];
  const productionCanaryKinds: readonly CodexProductionCanaryKind[] = [
    'account',
    'quota',
    'login',
    'app-server',
    'thread-turn',
    'approval',
    'worktree',
    'draft-pr',
    'live-smoke',
  ];
  const productionDriftGateKinds: readonly CodexProductionDriftGateKind[] = [
    'app-server-protocol',
    'desktop-target',
    'electron-target',
    'combined',
  ];
  const businessQuotaPermissionRoles: readonly BusinessQuotaPermissionRole[] = [
    'owner',
    'admin',
    'analytics_viewer',
    'member',
    'unknown',
  ];
  function normalizeProductionGaScenario(
    scenario: ProductionGaRequestBody['scenario'],
  ): ProductionGaE2EScenario {
    return scenario && productionGaScenarios.includes(scenario) ? scenario : 'all-pass';
  }

  function normalizeProductionCanaryKind(
    canaryKind: ProductionGaRequestBody['canaryKind'],
  ): CodexProductionCanaryKind {
    return canaryKind && productionCanaryKinds.includes(canaryKind) ? canaryKind : 'thread-turn';
  }

  function normalizeProductionDriftGateKind(
    gateKind: ProductionGaRequestBody['gateKind'],
  ): CodexProductionDriftGateKind {
    return gateKind && productionDriftGateKinds.includes(gateKind)
      ? gateKind
      : 'app-server-protocol';
  }

  function normalizeBusinessQuotaPermissionRole(
    role: BusinessQuotaDebugRequestBody['role'],
  ): BusinessQuotaPermissionRole {
    return role && businessQuotaPermissionRoles.includes(role) ? role : 'unknown';
  }

  function hasForbiddenProductionGaBody(value: unknown): boolean {
    const forbiddenKeys = new Set([
      'approvalArtifact',
      'executionAuthority',
      'authority',
      'childArtifact',
      'childArtifacts',
      'rawE2EPayload',
      'e2ePayload',
      'rawDocs',
      'rawDocument',
      'documentBody',
      'rawPath',
      'path',
      'rawCanary',
      'rawCanaryOutput',
      'rawCheck',
      'rawSchema',
      'schemaBody',
      'rawTarget',
      'rawAudit',
      'rawAuditRecord',
      'rawReadinessData',
      `to${'ken'}`,
      `coo${'kie'}`,
      'session',
      `m${'fa'}`,
      'storage',
      'requestBody',
      'responseBody',
    ]);

    if (!value || typeof value !== 'object') {
      return false;
    }

    if (Array.isArray(value)) {
      return value.some((item) => hasForbiddenProductionGaBody(item));
    }

    return Object.entries(value as Record<string, unknown>).some(
      ([key, nestedValue]) =>
        forbiddenKeys.has(key) ||
        hasForbiddenGithubRawBody(nestedValue) ||
        hasForbiddenRuntimeExternalAgentBody(nestedValue) ||
        hasForbiddenProductionGaBody(nestedValue),
    );
  }

  function hasForbiddenBusinessQuotaDebugBody(value: unknown): boolean {
    const forbiddenKeys = new Set([
      'authority',
      'executionAuthority',
      'rawSource',
      'rawExport',
      'rawProfile',
      'rawPage',
      'rawIdentity',
      'rawAccount',
      'rawWorkspace',
      'rawPath',
      'rawBody',
      'requestBody',
      'responseBody',
      'profilePath',
      'accountId',
      'workspaceId',
      'domText',
      'networkBody',
      `em${'ail'}`,
      `to${'ken'}`,
      `coo${'kie'}`,
      'session',
      `m${'fa'}`,
      'storage',
    ]);

    if (!value || typeof value !== 'object') {
      return false;
    }

    if (Array.isArray(value)) {
      return value.some((item) => hasForbiddenBusinessQuotaDebugBody(item));
    }

    return Object.entries(value as Record<string, unknown>).some(
      ([key, nestedValue]) =>
        forbiddenKeys.has(key) ||
        hasForbiddenGithubRawBody(nestedValue) ||
        hasForbiddenRuntimeExternalAgentBody(nestedValue) ||
        hasForbiddenProductionGaBody(nestedValue) ||
        hasForbiddenBusinessQuotaDebugBody(nestedValue),
    );
  }

  function createDefaultProductionGaThreatModel(
    unresolvedCriticalRiskCount = 0,
  ): ProductionGaThreatModel {
    return createProductionGaThreatModel({
      assetSeeds: ['store', 'approval-records', 'evidence-audit', 'operator-workflows'],
      trustBoundarySeeds: ['supervisor-local-control', 'store-resolved-child-records'],
      liveBoundarySeeds: ['github', 'deployment', 'browser-electron-mcp', 'external-agents'],
      authorityModelSeed: 'security-kernel-final-authority',
      approvalModelSeed: 'store-resolved-two-approval-ga-signoff',
      evidenceAuditModelSeed: 'evidence-audit-remain-authoritative',
      rollbackModelSeed: 'platform-operations-disaster-recovery-runbook',
      residualRiskCount: unresolvedCriticalRiskCount,
      unresolvedCriticalRiskCount,
    });
  }

  function createProductionGaReadinessPlanRecord(
    body: ProductionGaRequestBody | undefined,
  ): {
    plan: ProductionGaReadinessPlan;
    threatModel: ProductionGaThreatModel;
    residualRiskRegister: ProductionGaResidualRiskRegister;
  } {
    const unresolvedCriticalRiskCount = Math.max(0, body?.unresolvedCriticalRiskCount ?? 0);
    const productionGaEnabled = process.env.CODEXHUB_PRODUCTION_GA_ENABLED === 'true';
    const matrix = createProductionGaCapabilityMatrix();
    const threatModel = createDefaultProductionGaThreatModel(unresolvedCriticalRiskCount);
    const residualRiskRegister = createProductionGaResidualRiskRegister({
      risks:
        unresolvedCriticalRiskCount > 0
          ? [{ severity: 'critical' as const, resolved: false }]
          : [],
      mitigationSeed: 'production-ga-metadata-only-risk-register',
    });
    const plan = createProductionGaReadinessPlan({
      matrix,
      threatModel,
      trainingModuleCount: productionGaTrainingModuleIds.length,
      blockReasons: [
        ...(body?.blockReasons ?? []),
        ...(productionGaEnabled ? [] : ['production_ga_disabled']),
        ...(unresolvedCriticalRiskCount > 0 ? ['unresolved_critical_risk'] : []),
      ],
    });

    return { plan, threatModel, residualRiskRegister };
  }

  async function resolveProductionGaDryRunRecord(
    store: CodexHubStore,
    id: string,
  ): Promise<ProductionGaReadinessPlan | undefined> {
    const directRecord = await store.productionGaDryRuns.getDryRun(id);
    if (directRecord) {
      return directRecord;
    }

    return (await store.productionGaDryRuns.listDryRuns({ dryRunId: id, limit: 1 }))[0];
  }

  async function resolveProductionGaSignoffPlanRecord(
    store: CodexHubStore,
    id: string,
  ): Promise<ProductionGaReleaseCandidateSignoffPlan | undefined> {
    const directRecord = await store.productionGaSignoffPlans.getSignoffPlan(id);
    if (directRecord) {
      return directRecord;
    }

    return (await store.productionGaSignoffPlans.listSignoffPlans({ dryRunId: id, limit: 1 }))[0];
  }

  function createProductionGaApprovalRecord(
    dryRunRecord: ProductionGaReadinessPlan,
    body: ProductionGaRequestBody | undefined,
    decision: 'approved' | 'denied' | 'revoked',
  ): ProductionGaApprovalArtifact {
    return createProductionGaApprovalArtifact({
      dryRunId: dryRunRecord.dryRunId,
      approver:
        body?.decidedBy ?? body?.requestedBy ?? body?.approver ?? foundationId('production_ga_operator'),
      decision,
      reason: body?.reason,
    });
  }

  function createProductionGaRehearsalRunRecord(
    body: ProductionGaRequestBody | undefined,
  ): ProductionGaE2ERehearsalRun {
    const scenario = normalizeProductionGaScenario(body?.scenario);
    const plan = createProductionGaE2ERehearsalPlan({
      scenario,
      liveSmokeMode: body?.liveSmokeMode ?? 'conditional',
    });

    return createProductionGaE2ERehearsalRun({
      plan,
      liveSmokeStatus: body?.liveSmokeStatus ?? 'readiness_blocked',
      liveSmokeBlockerCount: body?.liveSmokeStatus === 'completed' ? 0 : 1,
    });
  }

  async function createProductionGaSignoffPlanRecord(
    store: CodexHubStore,
    body: ProductionGaRequestBody | undefined,
  ): Promise<ProductionGaReleaseCandidateSignoffPlan> {
    if (body?.signoffPlanId) {
      const existingPlan = await resolveProductionGaSignoffPlanRecord(store, body.signoffPlanId);
      if (existingPlan) {
        return existingPlan;
      }
    }

    const dryRunRecord = body?.dryRunId
      ? await resolveProductionGaDryRunRecord(store, body.dryRunId)
      : undefined;
    if (!dryRunRecord) {
      throw new Error('production GA dry-run was not found');
    }

    const matrix = createProductionGaCapabilityMatrix();
    const threatModel = createDefaultProductionGaThreatModel(
      body?.unresolvedCriticalRiskCount ?? 0,
    );
    const readinessSummary = summarizeProductionGaReadiness({
      plan: dryRunRecord,
      matrixStatus: body?.matrixStatus,
      threatModelStatus: body?.threatModelStatus,
      trainingStatus: body?.trainingStatus,
      e2eFixtureStatus: body?.e2eFixtureStatus,
      conditionalLiveStatus: body?.conditionalLiveStatus,
      unresolvedCriticalRiskCount: body?.unresolvedCriticalRiskCount,
      blockerCount: dryRunRecord.blockReasons.length,
    });
    const rehearsalRun =
      body?.scenario || body?.status || body?.liveSmokeStatus
        ? createProductionGaRehearsalRunRecord(body)
        : createProductionGaE2ERehearsalRun({
            plan: createProductionGaE2ERehearsalPlan({ scenario: 'all-pass' }),
            status: 'ready',
          });
    const signoffPlan = createProductionGaReleaseCandidateSignoffPlan({
      matrix,
      threatModel,
      readinessSummary,
      e2eRehearsalRun: rehearsalRun,
      unresolvedCriticalRiskCount: body?.unresolvedCriticalRiskCount,
      blockReasons: body?.blockReasons ?? dryRunRecord.blockReasons,
    });
    await store.productionGaSignoffPlans.saveSignoffPlan(signoffPlan);
    await store.productionGaE2ERehearsalRuns.saveRehearsalRun(rehearsalRun);
    return signoffPlan;
  }

  async function resolveProductionGaApprovals(
    store: CodexHubStore,
    body: ProductionGaRequestBody | undefined,
  ): Promise<ProductionGaApprovalArtifact[]> {
    const approvalIds = [
      ...(body?.approvalArtifactIds ?? []),
      ...(body?.approvalArtifactId ? [body.approvalArtifactId] : []),
    ];
    const approvals = await Promise.all(
      approvalIds.map((id) => store.productionGaApprovals.getApprovalByArtifactId(id)),
    );

    return approvals.filter((approval): approval is ProductionGaApprovalArtifact => Boolean(approval));
  }

  function createProductionGaSignoffBlockedResponse(reason: string, approvalCount = 0) {
    return {
      status: 'blocked',
      reason,
      requiredApprovalCount: 2,
      approvalCount,
      approvalConsumedCount: 0,
      processBoundaryInvoked: false,
      networkBoundaryInvoked: false,
      remoteProviderBoundaryInvoked: false,
      childAdapterInvokedDirectly: false,
      summary: 'Production GA signoff blocked before any child control-plane coordination.',
    };
  }

  function registerProductionReadinessRoutes(prefix: string): void {
    server.get(`${prefix}/canary-tasks`, async (request) => {
      const store = await getStore();
      const query = parseReviewPackageQuery(request.query);
      const records = store ? await store.codexProductionCanaryTasks.listRecords(query) : [];
      return createControlPlaneListResponse(records, (record) => record, store, false);
    });

    server.get(`${prefix}/canary-runs`, async (request) => {
      const store = await getStore();
      const query = parseReviewPackageQuery(request.query);
      const records = store ? await store.codexProductionCanaryRuns.listRecords(query) : [];
      return createControlPlaneListResponse(records, (record) => record, store, false);
    });

    server.get(`${prefix}/drift-gates`, async (request) => {
      const store = await getStore();
      const query = parseReviewPackageQuery(request.query);
      const records = store ? await store.codexProductionDriftGates.listRecords(query) : [];
      return createControlPlaneListResponse(records, (record) => record, store, false);
    });

    server.get(`${prefix}/readiness-gates`, async (request) => {
      const store = await getStore();
      const query = parseReviewPackageQuery(request.query);
      const records = store ? await store.codexProductionReadinessGates.listRecords(query) : [];
      return createControlPlaneListResponse(records, (record) => record, store, false);
    });

    server.get(`${prefix}/audit-exports`, async (request) => {
      const store = await getStore();
      const query = parseReviewPackageQuery(request.query);
      const records = store
        ? await store.codexProductionAuditExportSummaries.listRecords(query)
        : [];
      return createControlPlaneListResponse(records, (record) => record, store, false);
    });

    server.post(`${prefix}/audit-exports`, async (request, reply) => {
      const store = await getStore();
      if (!store) {
        return reply.code(503).send(createNewSurfaceStoreUnavailableResponse('production-readiness'));
      }
      const body = request.body as ProductionGaRequestBody | undefined;
      if (
        hasUntrustedAuthorityBody(body) ||
        hasForbiddenGithubRawBody(body) ||
        hasForbiddenRuntimeExternalAgentBody(body) ||
        hasForbiddenProductionGaBody(body)
      ) {
        return reply.code(400).send(createNewSurfaceRejectedBodyResponse(body?.dryRunId));
      }
      const [canaryRuns, driftGates, readinessGates] = await Promise.all([
        store.codexProductionCanaryRuns.listRecords({ limit: 50 }),
        store.codexProductionDriftGates.listRecords({ limit: 50 }),
        store.codexProductionReadinessGates.listRecords({ limit: 50 }),
      ]);
      const recordSeeds = body?.recordSeeds ?? [
        ...canaryRuns.map((record) => record.id),
        ...driftGates.map((record) => record.id),
        ...readinessGates.map((record) => record.id),
      ];
      const auditExportSummary = createCodexProductionAuditExportSummary({
        exportSeed: body?.exportSeed ?? 'production-readiness-audit-export',
        manifestSeed: body?.manifestSeed ?? 'production-readiness-audit-manifest',
        recordSeeds,
        auditEventIds: body?.auditEventIds,
      });

      await store.codexProductionAuditExportSummaries.saveRecord(auditExportSummary);

      return {
        status: 'planned',
        auditExportSummary,
        recordCount: auditExportSummary.recordCount,
        metadataOnly: true,
        processBoundaryInvoked: false,
        externalProcessStarted: false,
        networkBoundaryInvoked: false,
        executionDisabled: true,
        summary: 'Production readiness audit export summary stores manifest hash and counts only.',
      };
    });

    server.get(`${prefix}/summary`, async () => {
      const store = await getStore();
      const [
        canaryTasks,
        canaryRuns,
        driftGates,
        readinessGates,
        auditExportSummaries,
      ] = store
        ? await Promise.all([
            store.codexProductionCanaryTasks.listRecords({ limit: 50 }),
            store.codexProductionCanaryRuns.listRecords({ limit: 50 }),
            store.codexProductionDriftGates.listRecords({ limit: 50 }),
            store.codexProductionReadinessGates.listRecords({ limit: 50 }),
            store.codexProductionAuditExportSummaries.listRecords({ limit: 50 }),
          ])
        : [[], [], [], [], []];
      const latestReadinessGate = readinessGates[0];

      return {
        status: latestReadinessGate?.status ?? 'blocked',
        canaryTaskCount: canaryTasks.length,
        canaryRunCount: canaryRuns.length,
        driftGateCount: driftGates.length,
        readinessGateCount: readinessGates.length,
        auditExportSummaryCount: auditExportSummaries.length,
        latestReadinessGateId: latestReadinessGate?.id,
        liveSmokeAllowed: latestReadinessGate?.liveSmokeAllowed ?? false,
        highRiskLiveTaskBlocked: latestReadinessGate?.highRiskLiveTaskBlocked ?? true,
        degraded: persistenceState.status !== 'ok',
        notPersisted: !store,
        processBoundaryInvoked: false,
        externalProcessStarted: false,
        networkBoundaryInvoked: false,
        executionDisabled: true,
        summary: 'Production readiness summary is a store projection only.',
      };
    });

    server.post(`${prefix}/rehearsals`, async (request, reply) => {
      const store = await getStore();
      if (!store) {
        return reply.code(503).send(createNewSurfaceStoreUnavailableResponse('production-readiness'));
      }
      const body = request.body as ProductionGaRequestBody | undefined;
      if (
        hasUntrustedAuthorityBody(body) ||
        hasForbiddenGithubRawBody(body) ||
        hasForbiddenRuntimeExternalAgentBody(body) ||
        hasForbiddenProductionGaBody(body)
      ) {
        return reply.code(400).send(createNewSurfaceRejectedBodyResponse(body?.dryRunId));
      }

      const canaryTask = createCodexProductionCanaryTask({
        canaryKind: normalizeProductionCanaryKind(body?.canaryKind),
        taskSeed: body?.taskSeed ?? 'production-readiness-canary-task',
        targetSeed: body?.targetSeed ?? 'production-readiness-target',
        dependencySeed: body?.dependencySeed,
        liveSmoke: body?.liveSmoke ?? false,
        approvalRequired: body?.liveSmoke === true,
      });
      const approvalWaiting = body?.approvalWaiting ?? (body?.liveSmoke === true && !body?.approvalArtifactSeed);
      const canaryRun = createCodexProductionCanaryRun({
        canaryTask,
        checkCount: body?.checkCount,
        passedCount: body?.passedCount ?? (body?.failedCount || body?.blockerCount ? 0 : 1),
        failedCount: body?.failedCount,
        blockerCount: body?.blockerCount,
        liveSmoke: body?.approvalArtifactSeed ? body?.liveSmoke : false,
        approvalArtifactSeed: body?.approvalArtifactSeed,
      });
      const baselineSeed = body?.baselineSeed ?? 'production-readiness-baseline';
      const driftGate = createCodexProductionDriftGate({
        gateKind: normalizeProductionDriftGateKind(body?.gateKind),
        baselineSeed,
        observedSeed: body?.observedSeed ?? baselineSeed,
        driftCount: body?.driftCount,
        blockerCount: body?.driftBlockerCount,
      });
      const auditExportSummary = createCodexProductionAuditExportSummary({
        exportSeed: body?.exportSeed ?? 'production-readiness-audit-export',
        manifestSeed: body?.manifestSeed ?? 'production-readiness-audit-manifest',
        recordSeeds: body?.recordSeeds ?? [
          canaryTask.id,
          canaryRun.id,
          driftGate.id,
        ],
      });
      const readinessGate = createCodexProductionReadinessGate({
        canaryRuns: [canaryRun],
        driftGates: [driftGate],
        auditExportSummary,
        approvalWaiting,
        liveSmokeRequested: body?.liveSmokeRequested ?? body?.liveSmoke ?? false,
      });

      await store.codexProductionCanaryTasks.saveRecord(canaryTask);
      await store.codexProductionCanaryRuns.saveRecord(canaryRun);
      await store.codexProductionDriftGates.saveRecord(driftGate);
      await store.codexProductionAuditExportSummaries.saveRecord(auditExportSummary);
      await store.codexProductionReadinessGates.saveRecord(readinessGate);

      return {
        status: readinessGate.status,
        canaryTask,
        canaryRun,
        driftGate,
        auditExportSummary,
        readinessGate,
        liveSmokeAllowed: readinessGate.liveSmokeAllowed,
        highRiskLiveTaskBlocked: readinessGate.highRiskLiveTaskBlocked,
        processBoundaryInvoked: false,
        externalProcessStarted: false,
        networkBoundaryInvoked: false,
        executionDisabled: true,
        summary: 'Production readiness rehearsal created metadata-only store projections.',
      };
    });

    server.post(`${prefix}/live-smoke-gates`, async (request, reply) => {
      const store = await getStore();
      if (!store) {
        return reply.code(503).send(createNewSurfaceStoreUnavailableResponse('production-readiness'));
      }
      const body = request.body as ProductionGaRequestBody | undefined;
      if (
        hasUntrustedAuthorityBody(body) ||
        hasForbiddenGithubRawBody(body) ||
        hasForbiddenRuntimeExternalAgentBody(body) ||
        hasForbiddenProductionGaBody(body)
      ) {
        return reply.code(400).send(createNewSurfaceRejectedBodyResponse(body?.dryRunId));
      }

      const readinessGate = body?.readinessGateId
        ? await store.codexProductionReadinessGates.getRecord(body.readinessGateId)
        : (await store.codexProductionReadinessGates.listRecords({ limit: 1 }))[0];
      if (!readinessGate) {
        return reply.code(404).send({
          error: 'production_readiness_gate_not_found',
          status: 'blocked',
          liveSmokeAllowed: false,
          highRiskLiveTaskBlocked: true,
          processBoundaryInvoked: false,
          externalProcessStarted: false,
          networkBoundaryInvoked: false,
          executionDisabled: true,
        });
      }
      if (
        readinessGate.status !== 'ready' ||
        !readinessGate.liveSmokeAllowed ||
        readinessGate.highRiskLiveTaskBlocked
      ) {
        return reply.code(409).send({
          status: 'blocked',
          reason: 'readiness_gate_blocks_live_smoke',
          readinessGateId: readinessGate.id,
          liveSmokeAllowed: false,
          highRiskLiveTaskBlocked: true,
          processBoundaryInvoked: false,
          externalProcessStarted: false,
          networkBoundaryInvoked: false,
          executionDisabled: true,
          summary: 'Live smoke gate blocked by production readiness metadata.',
        });
      }
      if (!body?.approvalArtifactSeed) {
        return reply.code(409).send({
          status: 'approval_waiting',
          reason: 'live_smoke_approval_required',
          readinessGateId: readinessGate.id,
          liveSmokeAllowed: false,
          highRiskLiveTaskBlocked: true,
          processBoundaryInvoked: false,
          externalProcessStarted: false,
          networkBoundaryInvoked: false,
          executionDisabled: true,
          summary: 'Live smoke gate requires an approval artifact hash before any probe record.',
        });
      }

      const canaryTask = createCodexProductionCanaryTask({
        canaryKind: 'live-smoke',
        taskSeed: body.taskSeed ?? readinessGate.id,
        targetSeed: body.targetSeed ?? readinessGate.id,
        liveSmoke: true,
        approvalRequired: true,
      });
      const canaryRun = createCodexProductionCanaryRun({
        canaryTask,
        checkCount: body.checkCount,
        passedCount: body.passedCount ?? (body.failedCount || body.blockerCount ? 0 : 1),
        failedCount: body.failedCount,
        blockerCount: body.blockerCount,
        liveSmoke: true,
        approvalArtifactSeed: body.approvalArtifactSeed,
      });

      await store.codexProductionCanaryTasks.saveRecord(canaryTask);
      await store.codexProductionCanaryRuns.saveRecord(canaryRun);

      return {
        status: canaryRun.status,
        readinessGateId: readinessGate.id,
        canaryTask,
        canaryRun,
        liveSmokeAllowed: true,
        highRiskLiveTaskBlocked: canaryRun.highRiskLiveTaskBlocked,
        processBoundaryInvoked: false,
        externalProcessStarted: false,
        networkBoundaryInvoked: false,
        executionDisabled: true,
        summary: 'Live smoke gate recorded approval-backed metadata only.',
      };
    });
  }

