  function getM59StringArray(value: unknown): string[] | undefined {
    if (!Array.isArray(value)) {
      return undefined;
    }

    return value.filter((item): item is string => typeof item === 'string' && item.length > 0);
  }

  function getM59OptionalString(value: unknown): string | undefined {
    return typeof value === 'string' && value.trim().length > 0 ? value : undefined;
  }

  function getM59NonnegativeInteger(value: unknown): number | undefined {
    if (typeof value === 'number' && Number.isFinite(value)) {
      return Math.max(0, Math.trunc(value));
    }

    if (typeof value === 'string' && value.trim().length > 0) {
      const parsed = Number(value);
      return Number.isFinite(parsed) ? Math.max(0, Math.trunc(parsed)) : undefined;
    }

    return undefined;
  }

  function getM59DiffStatus(
    value: unknown,
  ): 'empty' | 'changed' | 'blocked' | 'unknown' | undefined {
    return value === 'empty' ||
      value === 'changed' ||
      value === 'blocked' ||
      value === 'unknown'
      ? value
      : undefined;
  }

  function getM59VerificationStatus(
    value: unknown,
  ): 'not_run' | 'planned' | 'running' | 'passed' | 'failed' | 'blocked' | 'aborted' | undefined {
    return value === 'not_run' ||
      value === 'planned' ||
      value === 'running' ||
      value === 'passed' ||
      value === 'failed' ||
      value === 'blocked' ||
      value === 'aborted'
      ? value
      : undefined;
  }

  function getM59ReviewStatus(
    value: unknown,
    reviewReady: unknown,
  ):
    | 'not_started'
    | 'ready_for_review'
    | 'blocked_verification'
    | 'blocked_patch'
    | 'pending'
    | 'approved'
    | 'changes_requested'
    | 'rejected'
    | undefined {
    if (reviewReady === true) {
      return 'ready_for_review';
    }

    return value === 'not_started' ||
      value === 'ready_for_review' ||
      value === 'blocked_verification' ||
      value === 'blocked_patch' ||
      value === 'pending' ||
      value === 'approved' ||
      value === 'changes_requested' ||
      value === 'rejected'
      ? value
      : undefined;
  }

  function getM59CiStatus(
    value: unknown,
  ): 'not_run' | 'pending' | 'passed' | 'failed' | 'blocked' | undefined {
    return value === 'not_run' ||
      value === 'pending' ||
      value === 'passed' ||
      value === 'failed' ||
      value === 'blocked'
      ? value
      : undefined;
  }

